package com.vocast.app;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class NovelNativePerformance {
 public static void main(String[] args)throws Exception{long start=System.nanoTime();File root=new File("artifacts/novel/performance");SnapshotStore store=new SnapshotStore(root);JSONObject full=store.load();long loaded=System.nanoTime();JSONArray books=full.getJSONArray("books"),chapters=books.getJSONObject(0).getJSONArray("chapters");int segments=0;for(int i=0;i<chapters.length();i++)segments+=chapters.getJSONObject(i).getJSONArray("segments").length();JSONObject chapter=chapters.getJSONObject(1);String header=new String(AudioFiles.read(new File(root,"library.json"),16*1024*1024),StandardCharsets.UTF_8);long saveStart=System.nanoTime();for(int i=0;i<20;i++){chapter.put("benchmark",i);store.save(header,new JSONArray().put(chapter).toString());}long end=System.nanoTime();Runtime runtime=Runtime.getRuntime();JSONObject result=new JSONObject().put("chapters",chapters.length()).put("segments",segments).put("loadMs",(loaded-start)/1e6).put("meanSaveMs",(end-saveStart)/20e6).put("heapUsedBytes",runtime.totalMemory()-runtime.freeMemory()).put("heapLimitBytes",runtime.maxMemory()).put("pass",true);try(FileOutputStream out=new FileOutputStream("artifacts/novel/performance/native-report.json")){out.write(result.toString(2).getBytes(StandardCharsets.UTF_8));}System.out.println(result.toString(2));}
}
